// Generated by 🤖
import { parseType } from './parse-type.mjs';
import { parseTable } from './parse-table.mjs';
import { parseElement } from './parse-element.mjs';
import { parseData } from './parse-data.mjs';
import { parseMemory } from './parse-memory.mjs';
import { parseExport } from './parse-export.mjs';
import { parseGlobal } from './parse-global.mjs';
import { parseFunction } from './parse-function.mjs';
import { parseImport } from './parse-import.mjs';
import { peekToken, getCurrentCursor, atEnd, skipToken } from './tape.mjs';
import { createError } from './parse-util.mjs';

export function parseModule() {
    const modulePos = getCurrentCursor();
    const module = {
        functions: [],
        exports: {},
        memories: [],
        datas: [],
        globals: [],
        tables: [],
        elements: [],  // Add elements array to store element segments
        start: null,   // Add start property to store the start function
        types: [],     // Add types array to store function types
        imports: [],   // Add imports array to store import declarations
        loc: modulePos // Changed from position to loc
    };

    while (!atEnd() && peekToken().value !== ')') { // check peekToken().value
        const currentToken = peekToken(); // Token for the opening parenthesis of a section
        if (currentToken && currentToken.value === '(') {
            skipToken() // Skip opening paren of sub-expression

            if (!atEnd()) {
                const sectionTypeToken = peekToken(); // This is the keyword token e.g. 'func', 'type'
                if (!sectionTypeToken) { // Should not happen if not atEnd and after '('
                    throw createError("Unexpected end of input after section opening '('.");
                }
                const sectionType = sectionTypeToken.value;
                // const sectionPos = { line: sectionTypeToken.line, column: sectionTypeToken.column }; // loc of the section keyword
                skipToken() // Skip section type token, its loc is captured by the specific parser

                if (sectionType === 'func') {
                    const func = parseFunction();
                    if (func) {
                        // Add function to the module's functions array
                        module.functions.push(func);

                        // Handle inline exports
                        if (func.export) {
                            module.exports[func.export] = {
                                kind: 'func',
                                index: module.functions.length - 1
                            };
                        }
                    }
                    skipToken() // Skip closing paren
                } else if (sectionType === 'import') {
                    // Generated by 🤖
                    // Parse import declaration
                    const importDecl = parseImport();
                    if (importDecl) {
                        module.imports.push(importDecl);

                        // If it's a function import, add it to the functions list as well
                        if (importDecl.kind === 'func' && importDecl.name) {
                            // Create a function object for the import
                            const importedFunc = {
                                name: importDecl.name,
                                parameters: importDecl.params.map((type, index) => ({
                                    name: index.toString(),
                                    type
                                })),
                                results: importDecl.results,
                                instructions: [],   // Imported function has no instructions
                                import: {
                                    module: importDecl.module,
                                    field: importDecl.field
                                },
                                loc: importDecl.loc // Changed from position to loc
                            };

                            // Add to module's functions list
                            module.functions.push(importedFunc);
                        }
                    }
                    skipToken() // Skip closing paren
                } else if (sectionType === 'memory') {
                    // Parse memory declaration
                    const memory = parseMemory();
                    if (memory) {
                        module.memories.push(memory);
                    }
                    skipToken() // Skip closing paren
                } else if (sectionType === 'data') {
                    // Parse data section
                    const data = parseData();
                    if (data) {
                        module.datas.push(data);
                    }
                    skipToken() // Skip closing paren
                } else if (sectionType === 'export') {
                    // Parse export section
                    const exportItem = parseExport();
                    if (exportItem?.name) {
                        if (exportItem.kind === 'func') {
                            // Find function index by name
                            let funcIndex = -1;
                            if (exportItem.index.startsWith('$')) {
                                funcIndex = module.functions.findIndex(f => f.name === exportItem.index);
                                if (funcIndex === -1) {
                                    throw createError(`Unknown exported function: ${exportItem.index}`);
                                }
                            } else {
                                funcIndex = Number.parseInt(exportItem.index, 10) || 0;
                            }
                            module.exports[exportItem.name] = {
                                kind: 'func',
                                index: funcIndex
                            };
                        } else if (exportItem.kind === 'memory') {
                            // Update memory export handling for multi-memory support
                            let memIndex = 0;

                            // For named memory references ($mem0, $mem1, etc.)
                            if (exportItem.index.startsWith('$')) {
                                const memoryName = exportItem.index;
                                // Find memory index by name
                                const memoryIdx = module.memories.findIndex(mem => mem.id === memoryName);
                                if (memoryIdx !== -1) {
                                    memIndex = memoryIdx;
                                } else {
                                    throw createError(`Unknown exported memory: ${memoryName}`);
                                }
                            } else {
                                // For numeric memory indices (0, 1, etc.)
                                memIndex = Number.parseInt(exportItem.index, 10) || 0;
                            }

                            module.exports[exportItem.name] = {
                                kind: 'memory',
                                index: memIndex
                            };
                        } else if (exportItem.kind === 'global') {
                            // Find global index by name
                            let globalIndex = -1;
                            if (exportItem.index.startsWith('$')) {
                                globalIndex = module.globals.findIndex(g => g.name === exportItem.index);
                                if (globalIndex === -1) {
                                    throw createError(`Unknown exported global variable: ${exportItem.index}`);
                                }
                            } else {
                                globalIndex = Number.parseInt(exportItem.index, 10) || 0;
                            }
                            module.exports[exportItem.name] = {
                                kind: 'global',
                                index: globalIndex
                            };
                        } else if (exportItem.kind === 'table') {
                            module.exports[exportItem.name] = {
                                kind: 'table',
                                index: Number.parseInt(exportItem.index, 10) || 0
                            };
                        }
                    }
                    skipToken() // Skip closing paren
                } else if (sectionType === 'global') {
                    // Handle global variable declaration
                    const global = parseGlobal();
                    if (global) {
                        module.globals.push(global);
                    }
                    skipToken() // Skip closing paren
                } else if (sectionType === 'table') {
                    // Add support for table declarations
                    const table = parseTable();
                    if (table) {
                        module.tables.push(table);
                    }
                    skipToken() // Skip closing paren
                } else if (sectionType === 'elem') {
                    // Parse element section
                    const elem = parseElement();
                    if (elem) {
                        module.elements.push(elem);
                    }
                    skipToken() // Skip closing paren
                } else if (sectionType === 'start') {
                    // Parse start section: (start $function) or (start <index>)
                    const startToken = peekToken();
                    if (startToken) {
                        module.start = {
                            value: startToken.value,
                            loc: { line: startToken.line, column: startToken.column }
                        };
                        skipToken(); // Consume the function reference token
                    } else {
                        throw createError("Unexpected end of input in start section.");
                    }
                    skipToken() // Skip closing paren
                } else if (sectionType === 'type') {
                    // Parse type section: (type $name (func (param i32 i32) (result i32)))
                    const typeDecl = parseType();
                    if (typeDecl) {
                        module.types.push(typeDecl);
                    }
                    skipToken() // Skip closing paren
                } else {
                    // Skip unrecognized sections
                    console.log("⚠️ Skipping unrecognized section:", sectionTypeToken);
                    while (!atEnd() && peekToken().value !== ')') {
                        skipToken()
                    }
                    if (peekToken().value === ')') { // Check before skipping
                        skipToken(); // Skip closing paren of unrecognized section
                    } else {
                        throw createError(`Unclosed section starting with '${sectionTypeToken.value}' at line ${sectionTypeToken.line}, column ${sectionTypeToken.column}`);
                    }
                }
            } else {
                 throw createError("Unexpected end of input after section opening '('.");
            }
        } else {
            // This case should ideally not be reached if WAT is well-formed inside a module,
            // as all module content should be s-expressions.
            const unexpectedToken = peekToken();
            throw createError(`Unexpected token '${unexpectedToken.value}' at line ${unexpectedToken.line}, column ${unexpectedToken.column} inside module. Expected '('.`);
        }
    }

    if (peekToken() && peekToken().value === ')') {
        skipToken(); // Skip the closing paren of the module
    } else {
        const errToken = peekToken();
        if (errToken) {
            throw createError(`Expected ')' to close module, but got '${errToken.value}' at line ${errToken.line}, column ${errToken.column}. Module started at line ${modulePos.line}, column ${modulePos.column}.`);
        } else {
            throw createError(`Expected ')' to close module, but found end of input. Module started at line ${modulePos.line}, column ${modulePos.column}.`);
        }
    }

    return module;
}